using Aspire.Hosting.Testing;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Base evaluation harness that boots the Aspire AppHost and exposes helpers
/// for running agentic evaluation scenarios against it.
/// </summary>
public class EvaluationHarness : IAsyncLifetime
{
    private DistributedApplication? _app;

    public HttpClient HttpClient { get; private set; } = default!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        builder.Services.ConfigureHttpClientDefaults(http =>
            http.AddStandardResilienceHandler());

        _app = await builder.BuildAsync();
        await _app.StartAsync();

        HttpClient = _app.CreateHttpClient("webfrontend", default);
    }

    public async ValueTask DisposeAsync()
    {
        if (_app is not null)
        {
            await _app.StopAsync();
            await _app.DisposeAsync();
        }
    }
}

using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Smoke-level evaluation tests that verify the agentic app starts correctly.
/// </summary>
public class SmokeTests : IClassFixture<EvaluationHarness>
{
    private readonly EvaluationHarness _harness;

    public SmokeTests(EvaluationHarness harness)
    {
        _harness = harness;
    }

    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        // The harness InitializeAsync already verifies the app can start.
        // A basic HTTP probe confirms it is serving traffic.
        var response = await _harness.HttpClient.GetAsync("/");
        Assert.True(
            response.IsSuccessStatusCode,
            $"Expected success status code but received {response.StatusCode}");
    }
}

